def depth_first_search(graph, start_node, end_node, visited=None):
    if visited is None:
        visited = set()
    visited.add(start_node)
    print(f"Visiting node: {start_node}")

    if start_node == end_node:
        return True

    for neighbor in graph.graph[start_node]:
